const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  const ledger = new Ledger();
  const seen = [];
  const service = new PaymentService(ledger, { acknowledge: async r => {
    seen.push(r);
    if (seen.length < 3) throw new Transient('retry');
  } });
  const receipt = await service.pay('shop', 'sale', 123);
  assert.equal(seen.length, 3);
  seen.forEach(r => assert.strictEqual(r, receipt));
  assert.equal(ledger.entries.length, 1);
  const concurrent = await Promise.all(Array.from({ length: 10 }, () => service.pay('shop', 'sale', 123)));
  concurrent.forEach(r => assert.strictEqual(r, receipt));
  await assert.rejects(service.pay('shop', 'sale', 124), /^Error: key conflict$/);
  assert.equal(ledger.entries.length, 1);
  await service.pay('other', 'sale', 124);
  assert.equal(ledger.entries.length, 2);

  const fresh = new Ledger();
  const results = await Promise.allSettled([fresh.apply('t', 'k', 1), fresh.apply('t', 'k', 2)]);
  assert.equal(results[0].status, 'fulfilled');
  assert.equal(results[1].reason.message, 'key conflict');
  assert.equal(fresh.entries.length, 1);

  let actions = 0;
  const invalid = new PaymentService({ apply: async () => { actions++; } }, {
    acknowledge: async () => { actions++; }
  });
  for (const attempts of [0, 6, -1, 1.5, NaN, Infinity, '3', null]) {
    await assert.rejects(invalid.pay('t', 'k', 1, attempts), /invalid payment/);
  }
  for (const args of [['', 'k', 1], ['t', '', 1], ['t', 'k', 0], ['t', 'k', 1.5], [1, 'k', 1]]) {
    await assert.rejects(invalid.pay(...args), /invalid payment/);
    await assert.rejects(fresh.apply(...args), /invalid payment/);
  }
  assert.equal(actions, 0);

  for (const error of [new Transient('final'), new Error('permanent')]) {
    let calls = 0;
    const failedLedger = new Ledger();
    const failing = new PaymentService(failedLedger, { acknowledge: async () => { calls++; throw error; } });
    await assert.rejects(failing.pay('t', 'k', 1, 5), e => e === error);
    assert.equal(calls, error instanceof Transient ? 5 : 1);
    assert.equal(failedLedger.entries.length, 1);
  }
}
module.exports = main();

